let locale

const isAfternoon = (input, isLowercase) => {
  const { meridiem } = locale || {}
  if (meridiem) {
    for (let h = 12; h < 24; h += 1) {
      if (meridiem(h, 0, isLowercase) === input) return true
    }
    return false
  }
  return input === (isLowercase ? 'pm' : 'PM')
}

const meridiemRegex = (baseRegex, isLowercase) => {
  const { meridiem } = locale || {}
  if (!meridiem) return baseRegex
  const parts = []
  for (let h = 0; h < 24; h += 1) {
    const s = meridiem(h, 0, isLowercase)
    if (s && parts.indexOf(s) < 0) parts.push(s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))
  }
  return parts.length ? new RegExp(`${baseRegex.source}|${parts.join('|')}`) : baseRegex
}

