import dayjs from '../src'
import customParseFormat from '../src/plugin/customParseFormat'
import '../../src/locale/zh-cn'

dayjs.extend(customParseFormat)

it('zh-cn meridiem round trip', () => {
  const format = 'YYYY年M月D日Ah点mm分ss秒'
  const input = '2018-05-02 01:02:03'
  const date = dayjs(input).locale('zh-cn').format(format)
  expect(date).toBe('2018年5月2日上午1点02分03秒')
  expect(dayjs(date, format, 'zh-cn').format('YYYY-MM-DD HH:mm:ss')).toBe('2018-05-02 01:02:03')
})

it('zh-cn pm meridiem round trip', () => {
  const format = 'YYYY年M月D日Ah点mm分ss秒'
  const input = '2018-05-02 13:02:03'
  const date = dayjs(input).locale('zh-cn').format(format)
  expect(date).toBe('2018年5月2日下午1点02分03秒')
  expect(dayjs(date, format, 'zh-cn').format('YYYY-MM-DD HH:mm:ss')).toBe('2018-05-02 13:02:03')
})

it('plain AM/PM still works', () => {
  expect(dayjs('2018-05-02 01:02:03 PM', 'YYYY-MM-DD HH:mm:ss A').format('HH:mm:ss')).toBe('13:02:03')
  expect(dayjs('2018-05-02 12:00 am', 'YYYY-MM-DD hh:mm a').format('HH:mm')).toBe('00:00')
})
EOF
